        raise KeyboardInterrupt()
    if ch == "\x04":
        raise EOFError()
    if echo_char:
        echo(ch, nl=False)
    return ch


def pause(info=None, err=False):
    if not is_interactive():
        return
    if info is None:
        info = "Press any key to continue..."
    echo(info, nl=False, err=err)
    getchar(True)
    echo("", err=err)


def edit(text=None, editor=None, env=None, require_save=True, extension=".txt", filename=None):
    if editor is None:
        editor = (
            (env or {}).get("EDITOR")
            or os.environ.get("VISUAL")
            or os.environ.get("EDITOR")
            or ("notepad" if sys.platform == "win32" else "vi")
        )
    command = shlex.split(editor)
    run_env = None
    if env:
        run_env = {**os.environ, **env}
    if filename is not None:
        subprocess.call(command + [os.fspath(filename)], env=run_env)
        return None
    original = text or ""
    fd, path = tempfile.mkstemp(suffix=extension)
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="") as f:
            f.write(original)
        subprocess.call(command + [path], env=run_env)
        with open(path, encoding="utf-8", newline="") as f:
            result = f.read()
    finally:
        os.remove(path)
    if require_save and result == original:
        return None
    return result


def clear():
    if not is_terminal(sys.stdout):
        return
    sys.stdout.write("\033[2J\033[H")
    sys.stdout.flush()


def _start_pager(color):
    pager = os.environ.get("PAGER") or "less"
    proc = subprocess.Popen(pager, shell=True, stdin=subprocess.PIPE)
    return proc


class _PagerWriter:
    def __init__(self, stream, keep_styles):
        self._stream = stream
        self._keep = keep_styles

    def write(self, text):
        if not self._keep:
            text = unstyle(text)
        self._stream.write(text.encode("utf-8"))
        self._stream.flush()
        return len(text)

    def flush(self):
        self._stream.flush()


def _chunks(text_or_generator):
    if isinstance(text_or_generator, str):
        return [text_or_generator]
    if callable(text_or_generator):
        return text_or_generator()
    return text_or_generator


def echo_via_pager(text_or_generator, color=None):
    chunks = _chunks(text_or_generator)
    if not is_interactive():
        for chunk in chunks:
            echo(chunk, nl=False, color=color)
        return
    proc = _start_pager(color)
    writer = _PagerWriter(proc.stdin, color is True)
    try:
        for chunk in chunks:
            writer.write(chunk)
    except BrokenPipeError:
        pass
    finally:
        try:
            proc.stdin.close()
        except BrokenPipeError:
            pass
        proc.wait()


class _EchoWriter:
    def __init__(self, color):
        self._color = color

    def write(self, text):
        echo(text, nl=False, color=self._color)
        return len(text)

    def flush(self):
        sys.stdout.flush()


@contextlib.contextmanager
def get_pager_file(color=None):
    if not is_interactive():
        yield _EchoWriter(color)
        return
    proc = _start_pager(color)
    writer = _PagerWriter(proc.stdin, color is True)
    try:
        yield writer
    finally:
        try:
            proc.stdin.close()
        except BrokenPipeError:
            pass
        proc.wait()


def _fmt_time(seconds):
    seconds = int(seconds)
    hours, rest = divmod(seconds, 3600)
    minutes, secs = divmod(rest, 60)
    return f"{hours}:{minutes:02d}:{secs:02d}"


class ProgressBar:
    def __init__(self, iterable=None, length=None, label=None, hidden=False, **options):
        self.iterable = iterable
        if length is None and iterable is not None and hasattr(iterable, "__len__"):
            length = len(iterable)
        self.length = length
        self.label = label or ""
        self.hidden = hidden
        self.pos = 0
        self.width = options.get("width", 36)
        self.start = time.time()
        self.is_tty = not hidden and is_terminal(sys.stdout)

    def __enter__(self):
        if not self.hidden and not self.is_tty and self.label:
            echo(self.label)
        return self

    def __exit__(self, exc_type, exc, tb):
        if self.is_tty:
            self._render()
            echo("")

    def __iter__(self):
        if self.iterable is None:
            raise TypeError("No iterable was given to the progress bar.")
        for item in self.iterable:
            yield item
            self.update(1)

    def update(self, n_steps):
        self.pos += n_steps
        if self.is_tty:
            self._render()

    def _render(self):
        if self.length:
            frac = min(self.pos / self.length, 1.0)
            filled = int(frac * self.width)
            bar = "#" * filled + "-" * (self.width - filled)
            elapsed = time.time() - self.start
            remaining = elapsed / self.pos * (self.length - self.pos) if self.pos else 0
            line = f"\r{self.label} [{bar}] {self.pos}/{self.length}  eta {_fmt_time(remaining)}"
        else:
            line = f"\r{self.label} {self.pos}"
        sys.stdout.write(line)
        sys.stdout.flush()


def progressbar(iterable=None, length=None, label=None, hidden=False, **options):
    return ProgressBar(iterable=iterable, length=length, label=label, hidden=hidden, **options)
