    def _value_for(self, param, name, first, it):
        if first is None and param.optional_value:
            return param.flag_value
        if first is None and param.prompt is not None:
            return _NEEDS_PROMPT
        tokens = [first] if first is not None else []
        while len(tokens) < param.nargs:
            if not it:
                raise BadOptionUsage(f"Option '{name}' requires an argument.", self.ctx)
            tokens.append(it.popleft())
        return tokens[0] if param.nargs == 1 else tuple(tokens)

    def _take(self, name, key, value, it):
        param, kind = self.options[key]
