            return False
        return self._process_stack(arg, it, largs)

    def parse(self, args):
        self.items = []
        largs = []
        literal_start = None
        it = list(args)
        it.reverse()
        seen_positional = False

        class _Queue(list):
            def popleft(self):
                return self.pop()

        it = _Queue(it)
        while it:
            arg = it.popleft()
            if arg == "--":
                literal_start = len(largs)
                largs.extend(reversed(list(it)))
                it.clear()
                break
